import java.util.Scanner;

public class Text_Document_Analysis {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        String s = scanner.next();

        StringBuilder underScore = new StringBuilder();
        StringBuilder bracket = new StringBuilder();

        int i = 0;
        while (i < n) {
            i = processChar(s, i, underScore, bracket);
        }

        underScore.append('_');
        bracket.append('_');

        int max = maxRun(underScore.toString());
        int max2 = countNonEmpty(bracket.toString());

        System.out.println(max + " " + max2);
    }

    private static int processChar(String s, int i, StringBuilder underScore, StringBuilder bracket) {
        if (s.charAt(i) == '(') {
            i++;
            while (s.charAt(i) != ')') {
                bracket.append(s.charAt(i));
                i++;
            }
            i++;
            bracket.append('_');
            underScore.append('_');
        } else {
            underScore.append(s.charAt(i));
            i++;
        }
        return i;
    }

    private static int maxRun(String str) {
        int max = 0;
        int count = 0;
        for (int i = 0; i < str.length(); i++) {
            if (str.charAt(i) == '_') {
                if (count > max) {
                    max = count;
                }
                count = 0;
            } else {
                count++;
            }
        }
        return max;
    }

    private static int countNonEmpty(String str) {
        int count = 0;
        int words = 0;
        for (int i = 0; i < str.length(); i++) {
            if (str.charAt(i) == '_') {
                if (count > 0) {
                    words++;
                }
                count = 0;
            } else {
                count++;
            }
        }
        return words;
    }
}
